import{_ as s,o as p,a as n,b as t}from"./app.C41L12d5.js";const W=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"Warp函数","link":"/api/SIMT-API/Warp_functions/Warp_functions"},{"text":"Warp函数简介","link":"/api/SIMT-API/Warp_functions/Warp_functions_intro"}]},"headers":[],"relativePath":"api/SIMT-API/Warp_functions/Warp_functions_intro.md","filePath":"api/SIMT-API/Warp_functions/Warp_functions_intro.md","outlineHeaders":[{"level":2,"title":"基本概念","slug":"基本概念","link":"#基本概念"},{"level":2,"title":"Warp函数分类","slug":"Warp函数分类","link":"#Warp函数分类"},{"level":2,"title":"典型场景","slug":"典型场景","link":"#典型场景"},{"level":3,"title":"Warp内条件汇总","slug":"Warp内条件汇总","link":"#Warp内条件汇总"},{"level":3,"title":"Warp内寄存器交换","slug":"Warp内寄存器交换","link":"#Warp内寄存器交换"},{"level":3,"title":"Warp内归约","slug":"Warp内归约","link":"#Warp内归约"},{"level":2,"title":"使用建议","slug":"使用建议","link":"#使用建议"}],"lastUpdated":1787050286000}'),l={name:"api/SIMT-API/Warp_functions/Warp_functions_intro.md"};function c(e,a,r,d,i,h){return p(),n("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>Warp函数</h1><p>Warp是SIMT线程执行和调度的基本单位。一个线程块内的线程会按照线性线程号被划分为多个Warp，当前一个Warp包含32个线程。同一Warp内的线程执行相同的指令流，但每个线程拥有独立的寄存器和Lane ID，可处理不同的数据地址和分支路径。</p><p>Warp函数用于同一Warp内的轻量级线程协作，常见能力包括条件投票、寄存器数据交换、Warp内归约和Lane信息查询。与通过Unified Buffer（UB）进行数据交换相比，Warp函数通常直接在Warp内完成寄存器级通信，适合小范围、低开销的线程协作场景。</p><h2 id="基本概念">基本概念<a class="header-anchor" href="#基本概念">​</a></h2><table><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>Warp</td><td>SIMT执行中的线程分组，当前一个Warp包含32个线程。</td></tr><tr><td>Lane</td><td>Warp内单个线程对应的执行位置。</td></tr><tr><td>Lane ID</td><td>线程在当前Warp内的编号，取值范围为[0, 31]。</td></tr><tr><td>活跃线程</td><td>当前指令路径上实际参与执行的线程。分支发散时，未进入当前路径的线程不参与该路径上的Warp函数计算。</td></tr><tr><td>分支发散</td><td>同一Warp内不同线程进入不同分支路径，硬件会分批执行不同路径，未执行当前路径的线程处于非活跃状态。</td></tr></tbody></table><h2 id="Warp函数分类">Warp函数分类<a class="header-anchor" href="#Warp函数分类">​</a></h2><table><thead><tr><th>类别</th><th>功能说明</th></tr></thead><tbody><tr><td>Warp Vote类函数</td><td>对Warp内活跃线程的条件值进行汇总，获取全真、任意为真、位图或活跃线程掩码。</td></tr><tr><td>Warp Shfl类函数</td><td>在Warp内按Lane ID交换寄存器数据，可用于邻近线程通信、扫描和归约。</td></tr><tr><td>Warp Reduce类函数</td><td>对Warp内活跃线程的输入值执行求和、最大值或最小值归约。</td></tr><tr><td>Lane ID类函数</td><td>获取当前线程的Lane ID或生成基于Lane ID的Lane Mask。</td></tr></tbody></table><h2 id="典型场景">典型场景<a class="header-anchor" href="#典型场景">​</a></h2><h3 id="Warp内条件汇总">Warp内条件汇总<a class="header-anchor" href="#Warp内条件汇总">​</a></h3><p>Vote类函数适合判断同一Warp内是否存在满足条件的线程，或将每个Lane的条件结果压缩成bit mask。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">active_mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_activemask</span><span class="p">();</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">hit_mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_ballot</span><span class="p">(</span><span class="n">value</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="n">threshold</span><span class="p">);</span>
<span class="kt">int32_t</span><span class="w"> </span><span class="n">has_hit</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_any</span><span class="p">(</span><span class="n">value</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="n">threshold</span><span class="p">);</span>
</code></pre></div><h3 id="Warp内寄存器交换">Warp内寄存器交换<a class="header-anchor" href="#Warp内寄存器交换">​</a></h3><p>Shfl类函数可直接读取同一Warp内其他Lane的寄存器值，减少通过UB共享内存中转数据的开销。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int32_t</span><span class="w"> </span><span class="n">lane</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">laneid</span><span class="p">();</span>
<span class="kt">int32_t</span><span class="w"> </span><span class="n">next_value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_shfl_down</span><span class="p">(</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
</code></pre></div><p>在使用Shfl类函数时，需要确保目标Lane处于活跃状态。如果目标Lane为非活跃状态，读取结果可能是未初始化值。</p><h3 id="Warp内归约">Warp内归约<a class="header-anchor" href="#Warp内归约">​</a></h3><p>Reduce类函数用于同一Warp内快速完成求和、最大值或最小值计算。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">float</span><span class="w"> </span><span class="n">warp_sum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_reduce_add</span><span class="p">(</span><span class="n">value</span><span class="p">);</span>
<span class="kt">float</span><span class="w"> </span><span class="n">warp_max</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_reduce_max</span><span class="p">(</span><span class="n">value</span><span class="p">);</span>
</code></pre></div><p>对于浮点归约，归约树的计算顺序可能与顺序累加不同，低位舍入结果可能存在差异。</p><h2 id="使用建议">使用建议<a class="header-anchor" href="#使用建议">​</a></h2><ul><li>Warp函数只在当前Warp内生效，不能用于跨Warp或跨线程块的数据同步。</li><li>Warp函数面向活跃线程执行。若代码存在分支发散，需要确认参与计算的Lane集合符合预期。</li><li>Shfl类函数读取其他Lane的寄存器值时，应避免读取非活跃Lane的数据。</li><li>Reduce类函数适合Warp内小范围归约；跨Warp或跨线程块归约通常需要结合UB、同步机制或原子操作。</li><li>Warp函数不等价于内存栅栏。需要约束内存可见性或线程块内阶段同步时，请使用<a href="../sync_and_memory_fence/sync_and_memory_fence.html">同步与内存栅栏</a>相关接口。</li></ul></article></div>`,1)])])}const _=s(l,[["render",c]]);export{W as __pageData,_ as default};
